update public.questions set body_hi = 'भारत के प्रशासनिक सुधार आयोगों (ARC) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: पहला ARC जनवरी 1966 में मोरारजी देसाई की अध्यक्षता में गठित हुआ (बाद में के. हनुमंतैया अध्यक्ष बने)। कथन 2 गलत है: दूसरा ARC 2005 में एम. वीरप्पा मोइली की अध्यक्षता में गठित हुआ। कथन 3 गलत है: दोनों ARC भारत सरकार के कार्यकारी संकल्पों से बने; अनुच्छेद 312 अखिल भारतीय सेवाओं से संबंधित है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["1966 में गठित पहले ARC के आरंभिक अध्यक्ष मोरारजी देसाई थे।", "दूसरा ARC 1999 में गठित हुआ।", "ARC संविधान के अनुच्छेद 312 के तहत स्थापित संवैधानिक निकाय हैं।"]}'::jsonb where id = '397efc06-74b5-4bed-ad54-fff443c64ecb' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'भारत में नागरिक-केंद्रित प्रशासन के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1, 2 और 4 सही हैं। भारत ने 1997 में नागरिक चार्टर का विचार अपनाया (ब्रिटेन ने इसे 1991 में शुरू किया था); DARPG ने सेवा-प्रदान में उत्कृष्टता के लिए सेवोत्तम मॉडल विकसित किया, जिसका बाद में दूसरे ARC ने समर्थन किया; और CPGRAMS, DARPG का ऑनलाइन शिकायत मंच है। कथन 3 गलत है: नागरिक चार्टर सेवा-मानकों की स्वैच्छिक घोषणाएँ हैं और न्यायालय में प्रवर्तनीय नहीं हैं; इन्हें प्रवर्तनीय बनाने वाला नागरिक चार्टर और शिकायत निवारण विधेयक, 2011 व्यपगत (lapse) हो गया।', updated_at = now(), question_data = question_data || '{"statements_hi": ["भारत में नागरिक चार्टर पहल 1997 में शुरू की गई, जो 1991 में ब्रिटेन में शुरू किए गए एक मॉडल पर आधारित थी।", "सेवोत्तम प्रशासनिक सुधार और लोक शिकायत विभाग (DARPG) द्वारा विकसित सेवा-प्रदान उत्कृष्टता का एक मॉडल है।", "केंद्रीय मंत्रालयों द्वारा जारी नागरिक चार्टर न्यायालय में कानूनी रूप से प्रवर्तनीय हैं।", "केंद्रीकृत लोक शिकायत निवारण और निगरानी प्रणाली (CPGRAMS) प्रशासनिक सुधार और लोक शिकायत विभाग चलाता है।"]}'::jsonb where id = '1d5fdd2f-d093-4c2a-acc3-c45a52561e36' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'मिशन कर्मयोगी के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'चारों कथन सही हैं। केंद्रीय मंत्रिमंडल ने सितंबर 2020 में मिशन कर्मयोगी (NPCSCB) को मंज़ूरी दी। इसका शीर्ष निकाय प्रधानमंत्री की लोक मानव संसाधन परिषद है, जिसके अध्यक्ष प्रधानमंत्री हैं। अप्रैल 2021 से कार्यरत क्षमता निर्माण आयोग वार्षिक क्षमता निर्माण योजनाओं को स्वीकृत करने में परिषद की सहायता करता है। 2022 में बनी पूर्णतः सरकारी स्वामित्व वाली धारा 8 (गैर-लाभकारी) कंपनी कर्मयोगी भारत iGOT-कर्मयोगी मंच की स्वामी है और उसे चलाती है। यह ''जाल की अनुपस्थिति'' वाला प्रश्न है: विद्यार्थी गलत कथन खोजता रहता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसे केंद्रीय मंत्रिमंडल ने 2020 में सिविल सेवा क्षमता निर्माण के राष्ट्रीय कार्यक्रम के रूप में मंज़ूरी दी।", "कार्यक्रम को रणनीतिक दिशा देने वाली प्रधानमंत्री की लोक मानव संसाधन परिषद की अध्यक्षता प्रधानमंत्री करते हैं।", "कार्यक्रम के तहत बना क्षमता निर्माण आयोग सरकारी विभागों की वार्षिक क्षमता निर्माण योजनाओं को स्वीकृत करने में सहायता करता है।", "एक गैर-लाभकारी कंपनी, कर्मयोगी भारत, iGOT-कर्मयोगी डिजिटल शिक्षण मंच की स्वामी है और उसका संचालन करती है।"]}'::jsonb where id = '4b4492dd-afb8-4b8f-bd4a-a488308b1eee' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'संगठनों और उन मंत्रालयों के निम्नलिखित युग्मों पर विचार कीजिए जिनके अधीन वे काम करते हैं:', explanation_hi = 'केवल युग्म 1 और 2 सही हैं। ऊर्जा दक्षता ब्यूरो विद्युत मंत्रालय के अधीन एक सांविधिक निकाय है (ऊर्जा संरक्षण अधिनियम, 2001), और केंद्रीय प्रदूषण नियंत्रण बोर्ड पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय के अधीन काम करता है। युग्म 3 नाम का जाल है: FSSAI (खाद्य सुरक्षा और मानक अधिनियम, 2006) खाद्य मंत्रालय के नहीं, स्वास्थ्य और परिवार कल्याण मंत्रालय के अधीन है। युग्म 4 गलत है: PFRDA श्रम मंत्रालय के नहीं, वित्त मंत्रालय (वित्तीय सेवा विभाग) के अधीन है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. ऊर्जा दक्षता ब्यूरो", "2. केंद्रीय प्रदूषण नियंत्रण बोर्ड", "3. भारतीय खाद्य सुरक्षा और मानक प्राधिकरण", "4. पेंशन निधि विनियामक और विकास प्राधिकरण"], "list_2_hi": ["विद्युत मंत्रालय", "पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय", "उपभोक्ता मामले, खाद्य और सार्वजनिक वितरण मंत्रालय", "श्रम और रोज़गार मंत्रालय"]}'::jsonb where id = '971fc0ae-c44b-447e-a48f-07027f82c96b' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'डिजिलॉकर के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं। डिजिलॉकर डिजिटल इंडिया के तहत इलेक्ट्रॉनिकी और सूचना प्रौद्योगिकी मंत्रालय का मंच है, और इसके माध्यम से जारी दस्तावेज़ सूचना प्रौद्योगिकी (डिजिटल लॉकर सुविधा देने वाले मध्यस्थों द्वारा सूचना का संरक्षण और प्रतिधारण) नियम, 2016 के तहत मूल भौतिक दस्तावेज़ों के समकक्ष माने जाते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["डिजिलॉकर डिजिटल इंडिया कार्यक्रम के तहत एक पहल है।", "सूचना प्रौद्योगिकी नियमों के तहत डिजिलॉकर के माध्यम से जारी दस्तावेज़ों को कानूनी रूप से मूल भौतिक दस्तावेज़ों के समकक्ष माना जाता है।"]}'::jsonb where id = 'c7e48422-b86f-4f72-8f8a-add3752c93d0' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं और कथन-II, कथन-I की व्याख्या करता है। चूँकि पुलिस और लोक व्यवस्था राज्य के विषय हैं (राज्य सूची की प्रविष्टि 1 और 2), इसलिए कोई केंद्रीय पुलिस एजेंसी किसी राज्य के क्षेत्र में अधिकार के रूप में काम नहीं कर सकती; इसीलिए DSPE अधिनियम की धारा 6 राज्य की सहमति (सामान्य या किसी विशेष मामले के लिए) अनिवार्य करती है, सिवाय उस स्थिति के जब कोई संवैधानिक न्यायालय CBI जाँच का निर्देश दे।', updated_at = now(), question_data = question_data || '{"assertion_hi": "दिल्ली विशेष पुलिस स्थापना अधिनियम, 1946 के तहत CBI को किसी राज्य के भीतर अपराध की जाँच के लिए सामान्यतः उस राज्य सरकार की सहमति चाहिए।", "reason_hi": "''पुलिस'' सातवीं अनुसूची की राज्य सूची का विषय है।"}'::jsonb where id = 'cf6d9370-7892-46e8-877d-d4a70e5e34f1' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'संसद सदस्य स्थानीय क्षेत्र विकास योजना (MPLADS) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं: प्रति सांसद वार्षिक अधिकार 5 करोड़ रुपये है, और योजना सांख्यिकी और कार्यक्रम कार्यान्वयन मंत्रालय चलाता है। कथन 2 गलत है: राज्यसभा का निर्वाचित सदस्य उसी राज्य के एक या अधिक ज़िलों में कार्यों की सिफ़ारिश कर सकता है जहाँ से वह निर्वाचित हुआ है, अपनी पसंद के किसी भी राज्य में नहीं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इस योजना के तहत हर संसद सदस्य प्रति वर्ष 5 करोड़ रुपये तक के कार्यों की सिफ़ारिश कर सकता है।", "राज्यसभा का निर्वाचित सदस्य अपनी पसंद के किसी भी राज्य के ज़िलों में कार्यों की सिफ़ारिश कर सकता है।", "यह योजना सांख्यिकी और कार्यक्रम कार्यान्वयन मंत्रालय द्वारा चलाई जाती है।"]}'::jsonb where id = 'eb0b6548-ec5e-4212-b0b7-afb2c39fb439' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = '2024 में दिए गए उच्चतम न्यायालय के निर्णयों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं: प्रॉपर्टी ओनर्स एसोसिएशन (नवंबर 2024) ने इस मत को अस्वीकार किया कि सारी निजी संपत्ति समुदाय का संसाधन है, और सीता सोरेन (मार्च 2024) ने विधायकों की रिश्वत के मामले में उन्मुक्ति पर पी.वी. नरसिम्हा राव (1998) को पलट दिया। कथन 2 निर्णय को उलट देता है: मिनरल एरिया डेवलपमेंट अथॉरिटी (जुलाई 2024) में न्यायालय ने 8:1 से कहा कि रॉयल्टी कर नहीं है और राज्यों को खनिज अधिकारों पर कर लगाने की शक्ति है। कथन 4 गलत है: सात न्यायाधीशों की पीठ (नवंबर 2024) ने अज़ीज़ बाशा (1967) को पलटा और कहा कि केवल कानून द्वारा निगमन से किसी संस्था का अल्पसंख्यक स्वरूप समाप्त नहीं होता।', updated_at = now(), question_data = question_data || '{"statements_hi": ["प्रॉपर्टी ओनर्स एसोसिएशन बनाम महाराष्ट्र राज्य में नौ न्यायाधीशों की पीठ ने कहा कि हर निजी स्वामित्व वाला संसाधन अनुच्छेद 39(ख) के तहत ''समुदाय का भौतिक संसाधन'' नहीं है।", "मिनरल एरिया डेवलपमेंट अथॉरिटी बनाम स्टील अथॉरिटी ऑफ़ इंडिया में न्यायालय ने कहा कि खनिजों पर रॉयल्टी एक कर है, इसलिए राज्य खनिज अधिकारों पर अलग से कर नहीं लगा सकते।", "सीता सोरेन बनाम भारत संघ में न्यायालय ने कहा कि सदन में मत या भाषण के संबंध में रिश्वत लेने पर विधायकों को अभियोजन से उन्मुक्ति नहीं है।", "अलीगढ़ मुस्लिम विश्वविद्यालय मामले में न्यायालय ने कहा कि किसी कानून द्वारा स्थापित संस्था कभी भी अनुच्छेद 30 के तहत अल्पसंख्यक दर्जे का दावा नहीं कर सकती।"]}'::jsonb where id = 'deed4af0-6de2-4149-b7c8-ee836bf0ae38' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'संशोधन शक्ति पर ऐतिहासिक निर्णयों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'चारों कथन सही हैं। गोलकनाथ (1967) ने कहा कि संसद मौलिक अधिकारों को कम नहीं कर सकती; केशवानंद भारती (1973) ने इसकी जगह मूल ढाँचे की सीमा रखी; मिनर्वा मिल्स (1980) ने 42वें संशोधन द्वारा जोड़े गए अनुच्छेद 368 के खंड (4) और (5) को रद्द किया, जो संशोधनों की न्यायिक समीक्षा पर रोक लगाते थे; और आई.आर. कोएल्हो (2007) ने कहा कि 24 अप्रैल 1973 (केशवानंद निर्णय की तिथि) के बाद नौवीं अनुसूची में डाले गए कानूनों की मूल ढाँचे के आधार पर समीक्षा हो सकती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["केशवानंद भारती (1973) में उच्चतम न्यायालय ने कहा कि संसद संविधान के मूल ढाँचे में संशोधन नहीं कर सकती।", "मिनर्वा मिल्स (1980) में उच्चतम न्यायालय ने 42वें संशोधन के वे खंड रद्द कर दिए जो संविधान संशोधनों की न्यायिक समीक्षा पर रोक लगाते थे।", "आई.आर. कोएल्हो (2007) में उच्चतम न्यायालय ने कहा कि 24 अप्रैल 1973 के बाद नौवीं अनुसूची में रखे गए कानूनों को मूल ढाँचे का उल्लंघन करने पर चुनौती दी जा सकती है।", "गोलकनाथ (1967) में उच्चतम न्यायालय ने कहा कि संसद मौलिक अधिकारों में संशोधन नहीं कर सकती।"]}'::jsonb where id = '8fb5d3e8-aedf-45c3-b07c-1a928893916a' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'किस मामले में उच्चतम न्यायालय ने कहा कि दसवीं अनुसूची के तहत अयोग्यता पर पीठासीन अधिकारी का निर्णय न्यायिक समीक्षा के अधीन है?', explanation_hi = 'किहोतो होलोहन (1992) में उच्चतम न्यायालय ने दसवीं अनुसूची को वैध माना, पर न्यायालयों का क्षेत्राधिकार हटाने वाले पैराग्राफ़ 7 को रद्द कर दिया और कहा कि पीठासीन अधिकारी एक अधिकरण की तरह कार्य करता है, जिसके निर्णय न्यायिक समीक्षा के अधीन हैं। एस.आर. बोम्मई (1994) राष्ट्रपति शासन से, नबाम रेबिया (2016) हटाने की सूचना का सामना कर रहे अध्यक्ष द्वारा अयोग्यता याचिकाओं पर निर्णय से, और इंद्रा साहनी (1992) OBC आरक्षण से संबंधित था।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "एस.आर. बोम्मई बनाम भारत संघ", "b": "नबाम रेबिया बनाम उपाध्यक्ष", "c": "किहोतो होलोहन बनाम ज़ाचिल्हू", "d": "इंद्रा साहनी बनाम भारत संघ"}'::jsonb as hi) h) where id = '5567c995-1418-4535-a6ea-ce03065a7fa4' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'उच्चतम न्यायालय के हाल के निर्णयों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। चुनावी बॉन्ड निर्णय (फ़रवरी 2024) ने योजना और उससे जुड़े संशोधनों को सूचना के अधिकार के उल्लंघन के कारण रद्द किया; दविंदर सिंह (अगस्त 2024) में सात न्यायाधीशों की पीठ ने ई.वी. चिन्नैया (2004) को पलटते हुए अनुसूचित जातियों के उप-वर्गीकरण की अनुमति दी; और अनुच्छेद 370 मामले (दिसंबर 2023) में 2019 के राष्ट्रपति आदेशों को वैध माना गया, साथ ही जल्द से जल्द राज्य का दर्जा बहाल करने और विधानसभा चुनाव कराने का निर्देश दिया गया।', updated_at = now(), question_data = question_data || '{"statements_hi": ["एसोसिएशन फ़ॉर डेमोक्रेटिक रिफ़ॉर्म्स बनाम भारत संघ (2024) में उच्चतम न्यायालय ने चुनावी बॉन्ड योजना को अनुच्छेद 19(1)(क) के तहत मतदाताओं के सूचना के अधिकार का उल्लंघन मानकर रद्द कर दिया।", "पंजाब राज्य बनाम दविंदर सिंह (2024) में उच्चतम न्यायालय ने कहा कि राज्य आरक्षण के लिए अनुसूचित जातियों का उप-वर्गीकरण कर सकते हैं।", "अनुच्छेद 370 मामले (2023) में उच्चतम न्यायालय ने जम्मू और कश्मीर के विशेष दर्जे की समाप्ति को संवैधानिक रूप से वैध ठहराया।"]}'::jsonb where id = '23cae2df-94b9-4ce8-bbfb-c47d76adefb3' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'संविधान के अनुच्छेदों और उनकी विषय-वस्तु के निम्नलिखित युग्मों पर विचार कीजिए:', explanation_hi = 'युग्म 1, 2 और 4 सही हैं। युग्म 3 गलत है: अनुच्छेद 32 मौलिक अधिकारों के प्रवर्तन के लिए उच्चतम न्यायालय जाने का अधिकार है; उच्च न्यायालयों की रिट जारी करने की शक्ति अनुच्छेद 226 में है, और यह अधिक व्यापक है क्योंकि यह मौलिक अधिकारों के अलावा ''किसी अन्य प्रयोजन'' तक भी फैली है।', updated_at = now(), question_data = question_data || '{"list_1_hi": ["1. अनुच्छेद 124", "2. अनुच्छेद 214", "3. अनुच्छेद 32", "4. अनुच्छेद 143"], "list_2_hi": ["उच्चतम न्यायालय की स्थापना और गठन", "राज्यों के लिए उच्च न्यायालय", "उच्च न्यायालयों की रिट जारी करने की शक्ति", "उच्चतम न्यायालय से परामर्श करने की राष्ट्रपति की शक्ति"]}'::jsonb where id = '14e471ab-bfc2-4d40-bf40-86c520c4f617' and exam_category = 'upsc' and jsonb_array_length(question_data->'list_1') = 4 returning id;
update public.questions set body_hi = 'भारत के उच्चतम न्यायालय के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। 34 न्यायाधीशों (मुख्य न्यायाधीश सहित) की वर्तमान संख्या संविधान ने नहीं, बल्कि अनुच्छेद 124(1) की अनुमति से संसद ने उच्चतम न्यायालय (न्यायाधीशों की संख्या) अधिनियम द्वारा तय की है। किसी न्यायाधीश को केवल राष्ट्रपति के आदेश से हटाया जा सकता है, जो संसद के प्रत्येक सदन द्वारा विशेष बहुमत से, सिद्ध कदाचार या असमर्थता के आधार पर, समावेदन (address) पारित होने के बाद दिया जाता है (अनुच्छेद 124(4))। अनुच्छेद 124(7) के तहत उच्चतम न्यायालय का सेवानिवृत्त न्यायाधीश भारत में किसी भी न्यायालय या प्राधिकारी के समक्ष वकालत या कार्य नहीं कर सकता।', updated_at = now(), question_data = question_data || '{"statements_hi": ["संविधान स्वयं उच्चतम न्यायालय के न्यायाधीशों की संख्या, मुख्य न्यायाधीश सहित, 34 निर्धारित करता है।", "उच्चतम न्यायालय के किसी न्यायाधीश को राष्ट्रपति भारत के मुख्य न्यायाधीश की सलाह पर हटा सकते हैं।", "उच्चतम न्यायालय का सेवानिवृत्त न्यायाधीश किसी भी उच्च न्यायालय में वकालत कर सकता है, पर उच्चतम न्यायालय में नहीं।"]}'::jsonb where id = 'eac329cd-3967-4dd9-b77d-1628bc2d8f73' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = '74वें संविधान संशोधन अधिनियम, 1992 के तहत नगरीय स्थानीय शासन के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। अनुच्छेद 243थ संक्रमणशील क्षेत्र के लिए नगर पंचायत, छोटे नगरीय क्षेत्र के लिए नगरपालिका परिषद और बड़े नगरीय क्षेत्र के लिए नगर निगम का प्रावधान करता है। अनुच्छेद 243यघ के तहत ज़िला योजना समिति ज़िले में पंचायतों और नगरपालिकाओं, दोनों द्वारा तैयार योजनाओं को समेकित करती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह ग्रामीण से नगरीय क्षेत्र में बदल रहे क्षेत्र के लिए नगर निगम का प्रावधान करता है।", "ज़िला योजना समिति केवल ज़िले की पंचायतों द्वारा तैयार योजनाओं को समेकित करती है।"]}'::jsonb where id = '985d42f3-249b-45cc-9544-f5263915127e' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'संविधान का कौन-सा अनुच्छेद पंचायतों की वित्तीय स्थिति की समीक्षा के लिए राज्य वित्त आयोग का प्रावधान करता है?', explanation_hi = 'अनुच्छेद 243झ राज्यपाल को हर पाँच वर्ष पर एक वित्त आयोग गठित करने के लिए बाध्य करता है, जो पंचायतों की वित्तीय स्थिति की समीक्षा करे और करों तथा अनुदानों के बँटवारे की सिफ़ारिश करे। अनुच्छेद 243छ पंचायतों की शक्तियों और कार्यों से, 243ज कर लगाने की उनकी शक्ति से, और 243ट राज्य निर्वाचन आयोग से संबंधित है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "अनुच्छेद 243छ", "b": "अनुच्छेद 243ज", "c": "अनुच्छेद 243ट", "d": "अनुच्छेद 243झ"}'::jsonb as hi) h) where id = 'cd1d49eb-65b3-4f9a-8926-e7d85167169e' and exam_category = 'upsc' returning id;
update public.questions set body_hi = '73वें संविधान संशोधन अधिनियम, 1992 के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है। कथन 2 गलत है: अनुच्छेद 243घ महिलाओं के लिए कम से कम एक-तिहाई सीटें (और अध्यक्ष पद) आरक्षित करता है; कई राज्यों में मिलने वाला आधा आरक्षण राज्य कानूनों से आता है। कथन 3 गलत है: अनुच्छेद 243घ(6) राज्य को पिछड़े वर्गों के लिए सीटें आरक्षित करने में केवल सक्षम बनाता है; यह एक स्वैच्छिक प्रावधान है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["इसने संविधान में भाग IX और ग्यारहवीं अनुसूची जोड़ी।", "यह हर पंचायत में कम से कम आधी सीटें महिलाओं के लिए आरक्षित करता है।", "यह हर राज्य के लिए पंचायतों में अन्य पिछड़े वर्गों के लिए सीटें आरक्षित करना अनिवार्य करता है।"]}'::jsonb where id = 'b2c20121-659e-4110-be57-15f9eb72ba43' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं, किंतु कथन-II, कथन-I की व्याख्या नहीं करता। अनुच्छेद 243ङ(4) फिर से गठित पंचायत को मूल पाँच वर्ष के कार्यकाल की शेष अवधि तक सीमित करता है, जबकि अनुच्छेद 243ङ(3)(ख) अलग से चुनाव कराने की छह महीने की समय-सीमा तय करता है। एक नियम नए निकाय के कार्यकाल के बारे में है, दूसरा चुनाव के समय के बारे में।', updated_at = now(), question_data = question_data || '{"assertion_hi": "किसी पंचायत के समय से पहले भंग होने के बाद गठित पंचायत केवल उस शेष अवधि तक बनी रहती है जिस तक भंग की गई पंचायत बनी रहती।", "reason_hi": "किसी पंचायत के गठन के लिए चुनाव उसके भंग होने की तिथि से छह महीने के भीतर पूरा होना चाहिए।"}'::jsonb where id = 'ce88db44-5069-491f-befe-c79449fd03ff' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'पंचायत उपबंध (अनुसूचित क्षेत्रों पर विस्तार) अधिनियम, 1996 (PESA) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'PESA की धारा 4 के अनुसार चारों कथन सही हैं: भाग IX, जो अन्यथा पाँचवीं अनुसूची के क्षेत्रों पर लागू नहीं होता (अनुच्छेद 243ड), संशोधनों के साथ इन पर लागू किया गया है; भूमि अधिग्रहण से पहले ग्राम सभा या उपयुक्त स्तर की पंचायत से परामर्श अनिवार्य है; अनुसूचित जनजातियों का आरक्षण कम से कम आधी सीटों का होना चाहिए; और हर स्तर पर सभी अध्यक्ष पद अनुसूचित जनजातियों के लिए आरक्षित हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यह संविधान के भाग IX को कुछ संशोधनों के साथ पाँचवीं अनुसूची के क्षेत्रों पर लागू करता है।", "अनुसूचित क्षेत्रों में विकास परियोजनाओं के लिए भूमि अधिग्रहण से पहले ग्राम सभा या उपयुक्त स्तर की पंचायत से परामर्श करना आवश्यक है।", "अनुसूचित क्षेत्रों की हर पंचायत में अनुसूचित जनजातियों के लिए आरक्षण कुल सीटों के कम से कम आधे के बराबर होना चाहिए।", "अनुसूचित क्षेत्रों में सभी स्तरों की पंचायतों के अध्यक्षों के सभी पद अनुसूचित जनजातियों के लिए आरक्षित हैं।"]}'::jsonb where id = '54ead7d2-7652-4bfd-92c0-5991526a7248' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'दोनों कथन सही हैं, किंतु कथन-II, कथन-I की व्याख्या नहीं करता। कथन-I सही है: अनुच्छेद 83 के तहत राज्यसभा भंग नहीं होती, जबकि लोकसभा पहले भंग न की जाए तो पाँच वर्ष तक चलती है। कथन-II सही है: अनुच्छेद 80(4) के तहत राज्यसभा के सदस्य राज्य विधानसभाओं के निर्वाचित सदस्यों द्वारा एकल संक्रमणीय मत के माध्यम से आनुपातिक प्रतिनिधित्व पद्धति से चुने जाते हैं। पर राज्यसभा इसलिए भंग नहीं होती कि वह एक स्थायी सदन है, जिसके एक-तिहाई सदस्य हर दूसरे वर्ष सेवानिवृत्त होते हैं (अनुच्छेद 83(1)); इसका कारण उनके निर्वाचन की पद्धति नहीं है।', updated_at = now(), question_data = question_data || '{"assertion_hi": "राज्यसभा भंग नहीं होती, जबकि लोकसभा को उसका कार्यकाल पूरा होने से पहले भंग किया जा सकता है।", "reason_hi": "राज्यसभा के सदस्यों को राज्य विधानसभाओं के निर्वाचित सदस्य एकल संक्रमणीय मत के माध्यम से आनुपातिक प्रतिनिधित्व पद्धति द्वारा चुनते हैं।"}'::jsonb where id = '5f289155-7caf-444e-bb49-1c8304c8308c' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'लोकसभा के पीठासीन अधिकारियों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1, 3 और 4 सही हैं: अस्थायी अध्यक्ष (प्रोटेम स्पीकर) की नियुक्ति राष्ट्रपति करते हैं; अनुच्छेद 94 के तहत उपाध्यक्ष अध्यक्ष को लिखकर त्यागपत्र देता है; और अनुच्छेद 110(3) के तहत कोई विधेयक धन विधेयक है या नहीं, इस पर अध्यक्ष का निर्णय अंतिम है। कथन 2 गलत है: विपक्ष के नेता को संवैधानिक नहीं, बल्कि संसद में विपक्ष के नेताओं के वेतन और भत्ते अधिनियम, 1977 के तहत सांविधिक मान्यता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["अस्थायी अध्यक्ष (प्रोटेम स्पीकर) की नियुक्ति राष्ट्रपति करते हैं।", "लोकसभा में विपक्ष के नेता के पद का प्रावधान संविधान में है।", "उपाध्यक्ष अध्यक्ष को संबोधित लिखित पत्र द्वारा पद से त्यागपत्र दे सकता है।", "कोई विधेयक धन विधेयक है या नहीं, इस पर अध्यक्ष का निर्णय अंतिम होता है।"]}'::jsonb where id = 'e4724313-83b4-48dc-88d4-950b4b0f95c4' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'संसद के कामकाज के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं: अनुच्छेद 100(3) के तहत गणपूर्ति (quorum) सदन की कुल सदस्य संख्या का दसवाँ भाग है, और अनुच्छेद 85 के तहत दो सत्रों के बीच का अंतर छह महीने से अधिक नहीं हो सकता। कथन 3 गलत है: अनुच्छेद 98 हर सदन को उसका अपना सचिवालय देता है, और लोकसभा सचिवालय किसी मंत्रालय के नहीं, अध्यक्ष के नियंत्रण में काम करता है; इससे यह कार्यपालिका से स्वतंत्र रहता है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["संसद के किसी भी सदन की बैठक के लिए गणपूर्ति उस सदन की कुल सदस्य संख्या का दसवाँ भाग है।", "संविधान के अनुसार संसद के दो सत्रों के बीच का अंतर छह महीने से अधिक नहीं होगा।", "लोकसभा का सचिवालय संसदीय कार्य मंत्रालय के नियंत्रण में काम करता है।"]}'::jsonb where id = 'f1559df4-2d56-42c2-bcc4-b7b7d2a6240d' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'संसद के दोनों सदनों की संयुक्त बैठक के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। अनुच्छेद 118(4) के तहत संयुक्त बैठक की अध्यक्षता लोकसभा अध्यक्ष करते हैं (उनकी अनुपस्थिति में उपाध्यक्ष, और फिर राज्यसभा के उपसभापति), राज्यसभा के सभापति नहीं। इस प्रावधान का प्रयोग केवल तीन बार हुआ है: दहेज प्रतिषेध विधेयक (1961), बैंकिंग सेवा आयोग (निरसन) विधेयक (1978) और आतंकवाद निवारण विधेयक (2002) के लिए।', updated_at = now(), question_data = question_data || '{"statements_hi": ["दोनों सदनों की संयुक्त बैठक की अध्यक्षता राज्यसभा के सभापति करते हैं।", "1950 से अब तक संयुक्त बैठक के प्रावधान का प्रयोग पाँच से अधिक बार हुआ है।"]}'::jsonb where id = 'b49b41b2-15b2-4b5e-a607-dfa33cfb931e' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 2 returning id;
update public.questions set body_hi = 'संसद की लोक लेखा समिति के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'तीनों कथन सही हैं। लोक लेखा समिति में 22 सदस्य होते हैं, 15 लोकसभा से और 7 राज्यसभा से। इसके अध्यक्ष की नियुक्ति लोकसभा अध्यक्ष करते हैं, और 1967 से परंपरा है कि अध्यक्ष विपक्ष से हो। यह केंद्र सरकार के विनियोग लेखाओं और वित्त लेखाओं पर CAG की लेखापरीक्षा रिपोर्टों की जाँच करती है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["लोक लेखा समिति में लोकसभा और राज्यसभा, दोनों के सदस्य होते हैं।", "इसके अध्यक्ष की नियुक्ति लोकसभा अध्यक्ष करते हैं, और 1967 से परंपरा के अनुसार अध्यक्ष विपक्ष से चुना जाता है।", "यह केंद्र सरकार के विनियोग लेखाओं और वित्त लेखाओं पर नियंत्रक-महालेखापरीक्षक की लेखापरीक्षा रिपोर्टों की जाँच करती है।"]}'::jsonb where id = 'e05cf0aa-4eac-412c-b9a8-18314cbcea09' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'संसदीय कार्यवाही के साधनों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 3 सही हैं: अल्प-सूचना प्रश्न दस दिन से कम की सूचना पर पूछा जाता है और उसका उत्तर मौखिक दिया जाता है, और शून्य काल (1962 से प्रचलित) एक अनौपचारिक साधन है जिसका प्रक्रिया नियमों में कोई उल्लेख नहीं है। कथन 2 गलत है: ध्यानाकर्षण प्रस्ताव 1954 से प्रचलित एक भारतीय नवाचार है, पर शून्य काल के विपरीत प्रक्रिया नियमों में इसका प्रावधान है।', updated_at = now(), question_data = question_data || '{"statements_hi": ["सार्वजनिक महत्त्व के किसी विषय पर दस दिन से कम की सूचना देकर अल्प-सूचना प्रश्न पूछा जा सकता है, और उसका उत्तर मौखिक दिया जाता है।", "ध्यानाकर्षण प्रस्ताव संसदीय प्रक्रिया में एक भारतीय नवाचार है, पर प्रक्रिया नियमों में इसका उल्लेख नहीं है।", "प्रक्रिया नियमों में शून्य काल का उल्लेख नहीं है।"]}'::jsonb where id = '3a0895ef-fecc-4816-b956-6abf5843b843' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'राज्यों में विधान परिषदों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'केवल कथन 1 सही है: अनुच्छेद 169 के तहत राज्य विधानसभा द्वारा विशेष बहुमत से पारित प्रस्ताव पर संसद विधान परिषद का सृजन या उत्सादन कर सकती है। कथन 2 अनुच्छेद 169(3) को उलट देता है: ऐसा कानून अनुच्छेद 368 के प्रयोजन के लिए संविधान का संशोधन स्पष्ट रूप से नहीं माना जाता, इसलिए इसके लिए केवल साधारण बहुमत चाहिए। कथन 3 गलत है: केवल छठा भाग सदस्य राज्यपाल द्वारा मनोनीत होते हैं; एक-तिहाई विधानसभा के सदस्यों द्वारा और एक-तिहाई स्थानीय निकायों द्वारा चुने जाते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["यदि किसी राज्य की विधानसभा विशेष बहुमत से प्रस्ताव पारित करे, तो संसद कानून बनाकर उस राज्य की विधान परिषद का सृजन या उत्सादन कर सकती है।", "संसद का ऐसा कानून अनुच्छेद 368 के प्रयोजन के लिए संविधान का संशोधन माना जाता है।", "विधान परिषद के एक-तिहाई सदस्य राज्यपाल द्वारा मनोनीत होते हैं।"]}'::jsonb where id = '5e96bc23-b156-48b4-a17a-6ae31f4c797c' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'संसद की वित्तीय समितियों के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कोई भी कथन सही नहीं है। सरकारी उपक्रमों संबंधी समिति में दोनों सदनों के सदस्य होते हैं (15 लोकसभा से और 7 राज्यसभा से)। प्राक्कलन समिति वह है जो केवल लोकसभा से बनती है; इसके सभी 30 सदस्य लोकसभा के होते हैं। लोकसभा की कार्य मंत्रणा समिति की अध्यक्षता सदन के नेता नहीं, अध्यक्ष करते हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["सरकारी उपक्रमों संबंधी समिति में केवल लोकसभा के सदस्य होते हैं।", "प्राक्कलन समिति में लोकसभा और राज्यसभा, दोनों के सदस्य होते हैं।", "लोकसभा की कार्य मंत्रणा समिति की अध्यक्षता सदन के नेता करते हैं।"]}'::jsonb where id = 'a4efe1b4-e1be-42c8-822a-e01e1f324755' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 3 returning id;
update public.questions set body_hi = 'संसद की विभाग-संबंधित स्थायी समितियों (DRSC) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:', explanation_hi = 'कथन 1 और 2 सही हैं: 1993 में शुरू हुई व्यवस्था 2004 में 24 समितियों तक बढ़ाई गई (16 का संचालन लोकसभा और 8 का राज्यसभा करती है), जिनमें से प्रत्येक में 31 सदस्य (21 + 10) होते हैं; मंत्री इनके सदस्य नहीं हो सकते। कथन 3 गलत है: 16 लोकसभा समितियों के अध्यक्षों की नियुक्ति लोकसभा अध्यक्ष करते हैं, पर 8 राज्यसभा समितियों के अध्यक्षों की नियुक्ति राज्यसभा के सभापति करते हैं। कथन 4 गलत है: DRSC की रिपोर्टें सलाहकारी होती हैं और सरकार पर बाध्यकारी नहीं हैं।', updated_at = now(), question_data = question_data || '{"statements_hi": ["कुल 24 DRSC हैं, जिनमें से 16 लोकसभा के अधीन और 8 राज्यसभा के अधीन काम करती हैं।", "हर DRSC में 31 सदस्य होते हैं: 21 लोकसभा से और 10 राज्यसभा से।", "हर DRSC के अध्यक्ष की नियुक्ति लोकसभा अध्यक्ष करते हैं।", "अनुदान माँगों पर DRSC की सिफ़ारिशें सरकार पर बाध्यकारी होती हैं।"]}'::jsonb where id = '4e380ee9-c96e-453e-b097-1f0b9977d177' and exam_category = 'upsc' and jsonb_array_length(question_data->'statements') = 4 returning id;
update public.questions set body_hi = 'राज्यों के बीच लोकसभा की सीटों का वर्तमान आवंटन किस जनगणना के जनसंख्या आँकड़ों पर आधारित है?', explanation_hi = 'राज्यों के बीच लोकसभा की सीटों का आवंटन 1971 की जनगणना के आधार पर स्थिर (freeze) है: 42वें संशोधन ने इसे 2000 तक स्थिर किया, और 84वें संशोधन (2001) ने यह स्थिरता 2026 के बाद होने वाली पहली जनगणना तक बढ़ा दी। 87वें संशोधन (2003) ने प्रति राज्य सीटों की संख्या बदले बिना राज्यों के भीतर निर्वाचन क्षेत्रों को 2001 की जनगणना के आधार पर फिर से निर्धारित करने की अनुमति दी; यही आकर्षक गलत उत्तर है।', updated_at = now(), options = (select jsonb_agg(case when h.hi ? (o.v->>'id') then o.v || jsonb_build_object('body_hi', h.hi->>(o.v->>'id')) else o.v end order by o.ord) from jsonb_array_elements(options) with ordinality o(v, ord), (select '{"a": "2011", "b": "2001", "c": "1991", "d": "1971"}'::jsonb as hi) h) where id = 'b10c4f75-9f1e-4c48-9026-cf8a98dd2bfd' and exam_category = 'upsc' returning id;
update public.questions set body_hi = 'यह कौन तय करता है कि कोई संसद सदस्य अनुच्छेद 102(1) के तहत, जैसे लाभ का पद धारण करने के कारण, अयोग्य हो गया है?', explanation_hi = 'अनुच्छेद 103 के तहत अनुच्छेद 102(1) की अयोग्यता के प्रश्नों का निर्णय राष्ट्रपति करते हैं, जिनका निर्णय अंतिम होता है, पर राष्ट्रपति को निर्वाचन आयोग की राय लेनी होती है और उसी के अनुसार कार्य करना होता है। इसके विपरीत, दल-बदल के आधार पर अयोग्यता (अनुच्छेद 102(2), दसवीं अनुसूची) का निर्णय अध्यक्ष या सभापति करते हैं।', updated_at = now() where id = '946bb8a0-1499-4592-a13d-8f1b07de751a' and exam_category = 'upsc' returning id;
